.tbp-launchpad{--am:#ffb000;--or:#ff7a00;--cy:#00c8d7;--gn:#2fe07a;--rd:#ff4a35;--dm:#8c6206;--ln:#2a1e05;box-sizing:border-box;width:100%;min-height:196px;background:#000;color:var(--am);font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:9px;line-height:1.1;font-variant-numeric:tabular-nums;border:1px solid var(--ln);outline:none;overflow:hidden}
.tbp-launchpad *{box-sizing:border-box}
.tbp-launchpad:focus-visible{border-color:var(--am)}
.tbp-launchpad .hd{display:flex;align-items:center;gap:5px;height:15px;padding:0 4px;background:#0d0900;border-bottom:1px solid var(--ln)}
