.tbp-launchpad .rail{width:80px;flex:0 0 80px;border-right:1px solid var(--ln);padding:2px 2px 3px;background:#050300}
.tbp-launchpad .rh{color:var(--dm);font-size:8px;letter-spacing:.06em;padding:2px 1px 1px;border-bottom:1px solid #170f00;margin-bottom:2px}
.tbp-launchpad .vw{display:flex;align-items:center;gap:3px;width:100%;height:14px;padding:0 2px;margin-bottom:1px;background:none;border:0;border-left:2px solid transparent;color:var(--am);font:inherit;font-size:8px;text-align:left;white-space:nowrap;cursor:pointer}
.tbp-launchpad .vw span{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis}
.tbp-launchpad .vw i{background:#1c1200;color:var(--or);font-style:normal;padding:0 2px}
.tbp-launchpad .vw b{margin-left:auto;color:var(--dm);font-weight:400}
.tbp-launchpad .vw:hover{background:#120c00}
