var views = root.querySelectorAll('.vw');
var grid = root.querySelector('.gr');
var clk = root.querySelector('.clk');
var panels = root.querySelector('.fp');
var px = root.querySelectorAll('.t1 .q');
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var vals = [5431.60, 19204.80, 2038.12, 13.24];
var digits = [2, 2, 2, 2];
var idx = 0;

function setView(i){
  idx = (i + views.length) % views.length;
  for (var v = 0; v < views.length; v++) views[v].classList.toggle('on', v === idx);
  grid.setAttribute('data-v', views[idx].getAttribute('data-v'));
  panels.textContent = views[idx].getAttribute('data-n') + ' PANELS';
}
for (var i = 0; i < views.length; i++){
  (function(n){ views[n].addEventListener('click', function(){ setView(n); root.focus(); }); })(i);
}
root.addEventListener('keydown', function(e){
  var k = e.key;
  if (k >= '1' && k <= '4'){ setView(parseInt(k, 10) - 1); e.preventDefault(); }
  else if (k === 'ArrowDown' || k === 'ArrowRight'){ setView(idx + 1); e.preventDefault(); }
  else if (k === 'ArrowUp' || k === 'ArrowLeft'){ setView(idx - 1); e.preventDefault(); }
});

function fmt(n, d){
  var s = n.toFixed(d).split('.');
  s[0] = s[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return s.join('.');
}
var t0 = 14 * 3600 + 32 * 60 + 7;
var tick = setInterval(function(){
  if (!root.isConnected){ clearInterval(tick); return; }
  t0 += 1;
  var h = Math.floor(t0 / 3600) % 24, m = Math.floor(t0 / 60) % 60, s = t0 % 60;
  clk.textContent = (h < 10 ? '0' : '') + h + ':' + (m < 10 ? '0' : '') + m + ':' + (s < 10 ? '0' : '') + s;
  if (t0 % 2) return;
  var j = Math.floor(Math.random() * vals.length);
  vals[j] = vals[j] * (1 + (Math.random() - 0.5) * 0.0009);
  var cell = px[j].querySelector('.px');
  cell.textContent = fmt(vals[j], digits[j]);
  if (reduce) return;
  cell.classList.remove('tk');
  void cell.offsetWidth;
  cell.classList.add('tk');
}, 1000);

