js:
var tabs = root.querySelectorAll('.pb');
var pgLbl = root.querySelector('.pg');
var last = root.querySelector('.lst');
var chg = root.querySelector('.chg');
var field = root.querySelector('.p1 .lit');
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var PREV = 213.07;
var px = 214.29;
var cur = 1;

function stagger(){
  var active = root.querySelector('.p' + cur);
  if (!active || reduce) return;
  var kids = active.querySelectorAll('.f, .r');
  for (var i = 0; i < kids.length; i++) kids[i].style.animationDelay = (i * 22) + 'ms';
}
function setPage(n){
  cur = n;
  root.setAttribute('data-p', String(n));
  pgLbl.textContent = n + '/4';
  for (var i = 0; i < tabs.length; i++) tabs[i].classList.toggle('on', tabs[i].getAttribute('data-p') === String(n));
  stagger();
}
for (var i = 0; i < tabs.length; i++){
  (function(t){
    t.addEventListener('click', function(){ setPage(parseInt(t.getAttribute('data-p'), 10)); root.focus(); });
  })(tabs[i]);
}
root.addEventListener('keydown', function(e){
  if (e.key >= '1' && e.key <= '4'){ setPage(parseInt(e.key, 10)); e.preventDefault(); }
  else if (e.key === 'ArrowRight'){ setPage(cur % 4 + 1); e.preventDefault(); }
  else if (e.key === 'ArrowLeft'){ setPage((cur + 2) % 4 + 1); e.preventDefault(); }
});
stagger();

var t = setInterval(function(){
  if (!root.isConnected){ clearInterval(t); return; }
  var step = (Math.random() - 0.47) * 0.09;
  px = Math.round((px + step) * 100) / 100;
  var d = Math.round((px - PREV) * 100) / 100;
  var p = d / PREV * 100;
  var up = d >= 0;
  last.textContent = px.toFixed(2);
  if (field) field.textContent = px.toFixed(2);
  chg.textContent = (up ? '+' : '') + d.toFixed(2) + ' · ' + (up ? '+' : '') + p.toFixed(2) + '%';
  chg.className = 'chg ' + (up ? 'up' : 'dn');
  if (reduce) return;
  chg.classList.remove('tk');
  void chg.offsetWidth;
  chg.classList.add('tk');
}, 1400);

