var svg = root.querySelector('.sv');
var gl = root.querySelector('.gl');
var ar = root.querySelector('.ar');
var ln = root.querySelector('.ln');
var vs = root.querySelector('.vs');
var yl = root.querySelector('.yl');
var xa = root.querySelector('.xa');
var ch = root.querySelector('.ch');
var cx = root.querySelector('.cx');
var dot = root.querySelector('.dot');
var btns = root.querySelectorAll('.p');
var dtE = root.querySelector('.dt');
var pxE = root.querySelector('.pxv');
var cgE = root.querySelector('.cg');
var mkE = root.querySelector('.mk');
var perE = root.querySelector('.per');
