var W = 300, H = 92, PAD = 5;
var cur = 2, ser = [], vols = [], lo = 0, hi = 0;

function rng(seed){
  var s = seed >>> 0;
  return function(){ s = (s * 1664525 + 1013904223) >>> 0; return s / 4294967296; };
