function money(n){
  var t = n.toFixed(2).split('.');
  t[0] = t[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return t.join('.');
}
function vfmt(n){ return n >= 1000 ? (n / 1000).toFixed(2) + 'B' : n.toFixed(1) + 'M'; }
function label(p, i){
  if (p.t){
    var mins = Math.round(i / (p.n - 1) * 390) + 570;
    var h = Math.floor(mins / 60), m = mins % 60;
    return (h < 10 ? '0' : '') + h + ':' + (m < 10 ? '0' : '') + m;
  }
  var d0 = Date.UTC(p.s[0], p.s[1], p.s[2]);
  var d1 = Date.UTC(p.e[0], p.e[1], p.e[2]);
  var d = new Date(d0 + (d1 - d0) * (i / (p.n - 1)));
  var dd = d.getUTCDate();
  return (dd < 10 ? '0' : '') + dd + '-' + MON[d.getUTCMonth()] + '-' + String(d.getUTCFullYear()).slice(2);
