for (var b = 0; b < btns.length; b++){
  (function(n){ btns[n].addEventListener('click', function(){ setP(n); root.focus(); }); })(b);
}
root.addEventListener('keydown', function(e){
  if (e.key === 'ArrowRight'){ setP(cur + 1); e.preventDefault(); }
  else if (e.key === 'ArrowLeft'){ setP(cur - 1); e.preventDefault(); }
});
draw();

