var rows = root.querySelectorAll('.bd .r');
var modes = root.querySelectorAll('.mb');
var ft = root.querySelector('.ft');
var DEF = ft.innerHTML;
var sel = -1;

function setMode(m){
  root.setAttribute('data-m', m);
  for (var i = 0; i < modes.length; i++) modes[i].classList.toggle('on', modes[i].getAttribute('data-m') === m);
}
function pick(i){
  if (i < 0 || i >= rows.length) return;
  if (sel > -1) rows[sel].classList.remove('sel');
  sel = i;
  var r = rows[i];
  r.classList.add('sel');
  var a = parseInt(r.getAttribute('data-a'), 10);
  var s = parseInt(r.getAttribute('data-s'), 10);
  var t = parseInt(r.getAttribute('data-t'), 10);
  var sign = function(v){ return (v >= 0 ? '+' : '') + v; };
  ft.innerHTML = '<b>' + r.getAttribute('data-n').toUpperCase() + '</b>&nbsp;' +
    r.getAttribute('data-h') + ' HLD · AW ' + r.getAttribute('data-w') + '% · AL ' +
    sign(a) + ' SE ' + sign(s) + ' = <b>' + sign(t) + 'bp</b>';
  ft.classList.remove('hit');
  void ft.offsetWidth;
  ft.classList.add('hit');
  if (r.scrollIntoView) r.scrollIntoView({ block: 'nearest' });
}
for (var i = 0; i < rows.length; i++){
  (function(n){ rows[n].addEventListener('click', function(){ pick(n); root.focus(); }); })(i);
}
for (var m = 0; m < modes.length; m++){
  (function(b){ b.addEventListener('click', function(){ setMode(b.getAttribute('data-m')); root.focus(); }); })(modes[m]);
}
root.addEventListener('keydown', function(e){
  if (e.key === 'ArrowDown'){ pick(sel < 0 ? 0 : Math.min(sel + 1, rows.length - 1)); e.preventDefault(); }
  else if (e.key === 'ArrowUp'){ pick(sel <= 0 ? 0 : sel - 1); e.preventDefault(); }
  else if (e.key === '1'){ setMode('a'); e.preventDefault(); }
  else if (e.key === '2'){ setMode('w'); e.preventDefault(); }
  else if (e.key === 'Escape'){
    if (sel > -1) rows[sel].classList.remove('sel');
    sel = -1; ft.innerHTML = DEF; e.preventDefault();
  }
});

