var rows = root.querySelectorAll('.bd .r');
var ft = root.querySelector('.ft');
var mk = root.querySelector('.mk');
var DEF = ft.innerHTML;
var sel = -1;

function pos(v){ return ((v - LO) / (HI - LO) * 100).toFixed(1) + '%'; }
root.querySelector('.mp').style.left = pos(PX);
root.querySelector('.mt').style.left = pos(MEAN);
var fill = root.querySelector('.fill');
fill.style.left = pos(PX);
fill.style.width = ((MEAN - PX) / (HI - LO) * 100).toFixed(1) + '%';

function pick(i){
  if (i < 0 || i >= rows.length) return;
  if (sel > -1) rows[sel].classList.remove('sel');
  sel = i;
  var r = rows[i];
  r.classList.add('sel');
  var t = parseFloat(r.getAttribute('data-t'));
  var p = parseFloat(r.getAttribute('data-p'));
  var up = (t - PX) / PX * 100;
  mk.style.left = pos(t);
  mk.classList.add('on');
