  ft.classList.remove('hit');
  void ft.offsetWidth;
  ft.classList.add('hit');
  if (r.scrollIntoView) r.scrollIntoView({ block: 'nearest' });
}
for (var i = 0; i < rows.length; i++){
  (function(n){ rows[n].addEventListener('click', function(){ pick(n); root.focus(); }); })(i);
}
root.addEventListener('keydown', function(e){
  if (e.key === 'ArrowDown'){ pick(sel < 0 ? 0 : Math.min(sel + 1, rows.length - 1)); e.preventDefault(); }
  else if (e.key === 'ArrowUp'){ pick(sel <= 0 ? 0 : sel - 1); e.preventDefault(); }
  else if (e.key === 'Escape'){
