var rows = root.querySelectorAll('.bd .r');
var ct = root.querySelector('.ct');
var ne = root.querySelector('.ne');
var ns = root.querySelector('.ns');
var fc = root.querySelector('.fc');
var fp = root.querySelector('.fp');
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var pend = [];
for (var i = 0; i < rows.length; i++) if (!rows[i].classList.contains('rel')) pend.push(rows[i]);
var done = rows.length - pend.length;
var at = 0, left = 0;

function clock(s){
  var h = Math.floor(s / 3600), m = Math.floor(s / 60) % 60, x = s % 60;
  return 'T-' + (h < 10 ? '0' : '') + h + ':' + (m < 10 ? '0' : '') + m + ':' + (x < 10 ? '0' : '') + x;
}
function arm(){
  if (at >= pend.length){
    ne.textContent = 'SESSION COMPLETE · 16-JUN 08:30 EMPIRE MFG';
    ns.textContent = 'SURV 12.0';
    ct.textContent = 'T-66:30:00';
    ct.classList.remove('warn');
    for (var j = 0; j < rows.length; j++) rows[j].classList.remove('due');
    return;
  }
  var r = pend[at];
  for (var k = 0; k < rows.length; k++) rows[k].classList.remove('due');
  r.classList.add('due');
  ne.textContent = r.getAttribute('data-t');
  ns.textContent = r.getAttribute('data-s');
  left = parseInt(r.getAttribute('data-w'), 10);
  ct.textContent = clock(left);
  ct.classList.remove('warn');
}
function print(){
  var r = pend[at];
  var cell = r.querySelector('.a');
  var dir = r.getAttribute('data-c');
  cell.textContent = r.getAttribute('data-a') + (dir === 'up' ? ' ▲' : ' ▼');
  cell.className = 'n a ' + dir;
  r.classList.add('rel');
  r.classList.remove('due');
  if (!reduce){
    r.classList.remove('hit');
    void r.offsetWidth;
    r.classList.add('hit');
  }
  done++;
  at++;
  fc.textContent = done + ' OF ' + rows.length + ' RELEASED';
  fp.textContent = (rows.length - done) + ' PENDING';
  arm();
}
arm();
var t = setInterval(function(){
  if (!root.isConnected){ clearInterval(t); return; }
  if (at >= pend.length) return;
  left--;
  if (left <= 0){ print(); return; }
  ct.textContent = clock(left);
  if (left <= 3) ct.classList.add('warn');
}, 1000);

