js:
var bd = root.querySelector('.bd');
var tabs = root.querySelectorAll('.fb');
var pf = root.querySelector('.pf');
var ps = root.querySelector('.ps');
var pt = root.querySelector('.pt');
var pb = root.querySelector('.pb');
var un = root.querySelector('.un');
var fu = root.querySelector('.fu');
var fm = root.querySelector('.fm');
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var empty = document.createElement('div');
empty.className = 'empty';
empty.textContent = 'NO MESSAGES IN THIS FOLDER · 0 OF 0';
var filt = 'all', sel = null;
var INBOX = [
  { cat:'ioi', fr:'SLS:KESTREL RESEARCH', sh:'SLS:KEST', sb:'OFFER 400K MSFT 3%', b:'NAT SELLER 400K MSFT US|WORKS 3% ADV · LIMIT 441.00|CROSS OPP WITH OUR AXE' },
  { cat:'rsc', fr:'RSC:EQUITY RESEARCH', sh:'RSC:EQTY', sb:'AAPL PT 245 fr 232', b:'RAISE PT TO 245 FROM 232 · BUY|FY26 EPS 7.40 FROM 7.05|SERVICES MIX DRIVES GROSS MARGIN' },
  { cat:'ops', fr:'PB:CLEARING', sh:'PB:CLEAR', sb:'CASH SWEEP 12.4MM', b:'SWEPT USD 12.4MM TO MMF|RATE 5.28% · T+0 LIQUIDITY|BAL AFTER SWEEP USD 1.9MM' }
];
var qi = 0, tnext = 11;

function rows(){ return root.querySelectorAll('.bd .r'); }
function counts(){
  var all = rows(), n = 0, u = 0, c = { ioi:0, rsc:0, ops:0 };
  for (var i = 0; i < all.length; i++){
    n++;
    if (all[i].classList.contains('nw')) u++;
    var k = all[i].getAttribute('data-cat');
    if (c[k] !== undefined) c[k]++;
  }
  root.querySelector('.c1').textContent = n;
  root.querySelector('.c2').textContent = c.ioi;
  root.querySelector('.c3').textContent = c.rsc;
  un.textContent = u ? u + ' NEW' : 'NO NEW';
  un.className = 'un' + (u ? '' : ' zero');
  fu.textContent = u + ' UNREAD';
  fu.className = 'fu' + (u ? '' : ' zero');
  fm.textContent = n + ' MSGS';
}
function show(r){
  if (sel) sel.classList.remove('sel');
  sel = r;
  r.classList.add('sel');
  pf.textContent = r.getAttribute('data-fr');
  ps.textContent = r.getAttribute('data-sb');
  pt.textContent = r.getAttribute('data-tm');
  pb.textContent = '';
  var parts = r.getAttribute('data-b').split('|');
  for (var i = 0; i < parts.length; i++){
    var d = document.createElement('div');
    d.textContent = parts[i];
    pb.appendChild(d);
  }
  if (r.scrollIntoView) r.scrollIntoView({ block: 'nearest' });
}
function wire(r){
  r.addEventListener('click', function(){ show(r); root.focus(); });
}
function visible(){
  var all = rows(), out = [];
  for (var i = 0; i < all.length; i++) if (!all[i].classList.contains('hide')) out.push(all[i]);
  return out;
}
function applyFilter(){
  var all = rows(), shown = 0;
  for (var i = 0; i < all.length; i++){
    var hit = filt === 'all' || all[i].getAttribute('data-cat') === filt;
    all[i].classList.toggle('hide', !hit);
    if (hit) shown++;
  }
  if (!shown){ if (!empty.parentNode) bd.appendChild(empty); }
  else if (empty.parentNode) bd.removeChild(empty);
  var vis = visible();
  if (vis.length && (!sel || sel.classList.contains('hide'))) show(vis[0]);
}
var NAMES = { all:'INBOX', ioi:'IOI / SALES', rsc:'RESEARCH', snt:'SENT' };
function setFilter(f){
  filt = f;
  root.querySelector('.tt').textContent = 'MESSAGES · ' + NAMES[f];
  for (var i = 0; i < tabs.length; i++) tabs[i].classList.toggle('on', tabs[i].getAttribute('data-f') === f);
  applyFilter();
}
var start = rows();
for (var i = 0; i < start.length; i++) wire(start[i]);
for (var t = 0; t < tabs.length; t++){
  (function(b){ b.addEventListener('click', function(){ setFilter(b.getAttribute('data-f')); root.focus(); }); })(tabs[t]);
}
root.addEventListener('keydown', function(e){
  var vis = visible();
  var idx = vis.indexOf(sel);
  if (e.key === 'ArrowDown'){ show(vis[Math.min(idx + 1, vis.length - 1)] || vis[0]); e.preventDefault(); }
  else if (e.key === 'ArrowUp'){ show(vis[Math.max(idx - 1, 0)] || vis[0]); e.preventDefault(); }
  else if (e.key === 'Enter'){
    if (sel && sel.classList.contains('nw')){ sel.classList.remove('nw'); counts(); }
    e.preventDefault();
  }
  else if (e.key >= '1' && e.key <= '4'){ setFilter(['all','ioi','rsc','snt'][parseInt(e.key, 10) - 1]); e.preventDefault(); }
});
counts();
show(start[0]);

var clk = 14 * 3600 + 31 * 60 + 6;
var t2 = setInterval(function(){
  if (!root.isConnected){ clearInterval(t2); return; }
  clk += 7;
  tnext--;
  if (tnext > 0 || qi >= INBOX.length) return;
  tnext = 13;
  var m = INBOX[qi++];
  var h = Math.floor(clk / 3600) % 24, mm = Math.floor(clk / 60) % 60, ss = clk % 60;
  var pad = function(v){ return (v < 10 ? '0' : '') + v; };
  var stamp = pad(h) + ':' + pad(mm) + ':' + pad(ss);
  var r = document.createElement('div');
  r.className = 'r nw in';
  r.setAttribute('tabindex', '-1');
  r.setAttribute('data-cat', m.cat);
  r.setAttribute('data-fr', m.fr);
  r.setAttribute('data-sb', m.sb);
  r.setAttribute('data-tm', stamp);
  r.setAttribute('data-b', m.b);
  var dot = document.createElement('s'); dot.className = 'dot';
  var fr = document.createElement('span'); fr.className = 'fr'; fr.textContent = m.sh;
  var sb = document.createElement('span'); sb.className = 'sb'; sb.textContent = m.sb;
  var tm = document.createElement('span'); tm.className = 'tm'; tm.textContent = stamp.slice(0, 5);
  r.appendChild(dot); r.appendChild(fr); r.appendChild(sb); r.appendChild(tm);
  if (reduce) r.classList.remove('in');
  bd.insertBefore(r, bd.firstChild);
  wire(r);
  applyFilter();
  counts();
  bd.scrollTop = 0;
}, 1000);

