@keyframes tbp-hp-table-fl{from{background:#241800}to{background:#0d0900}}
@media (prefers-reduced-motion:reduce){
.tbp-hp-table .ft.hit{animation:none}
}

js:
var bd = root.querySelector('.bd');
var heads = root.querySelectorAll('.so');
var ft = root.querySelector('.ft');
var DEF = ft.innerHTML;
var all = [], sel = -1, key = 'k', dir = -1;
var nodes = root.querySelectorAll('.bd .r');
for (var i = 0; i < nodes.length; i++) all.push(nodes[i]);

function num(el, k){ return parseFloat(el.getAttribute('data-' + k)); }
function sort(k, t){
  if (key === k) dir = -dir; else { key = k; dir = -1; }
  all.sort(function(a, b){
    var av = num(a, k), bv = num(b, k);
    return (av - bv) * dir;
  });
  for (var i = 0; i < all.length; i++) bd.appendChild(all[i]);
  for (var h = 0; h < heads.length; h++){
    var on = heads[h].getAttribute('data-s') === k;
    heads[h].classList.toggle('act', on);
    heads[h].querySelector('u').textContent = on ? (dir < 0 ? '▼' : '▲') : '';
  }
}
function pick(i){
  if (i < 0 || i >= all.length) return;
  if (sel > -1 && all[sel]) all[sel].classList.remove('sel');
  sel = i;
  var r = all[i];
  r.classList.add('sel');
  var c = num(r, 'c'), p = num(r, 'p');
  ft.innerHTML = '<span class="fd"><b>' + r.getAttribute('data-d') + '</b> O ' + r.getAttribute('data-o') +
    ' H ' + r.getAttribute('data-h') + ' L ' + r.getAttribute('data-l') + ' C <b class="' +
    (p >= 0 ? 'up' : 'dn') + '">' + c.toFixed(2) + '</b> RNG <b>' + r.getAttribute('data-rp') + '%</b></span>';
  ft.classList.remove('hit');
  void ft.offsetWidth;
  ft.classList.add('hit');
  if (r.scrollIntoView) r.scrollIntoView({ block: 'nearest' });
}
for (var a = 0; a < all.length; a++){
  all[a].addEventListener('click', function(){ pick(all.indexOf(this)); root.focus(); });
}
for (var h = 0; h < heads.length; h++){
  (function(el){
    el.addEventListener('click', function(){ sort(el.getAttribute('data-s'), el.getAttribute('data-t')); root.focus(); });
  })(heads[h]);
}
root.addEventListener('keydown', function(e){
  if (e.key === 'ArrowDown'){ pick(sel < 0 ? 0 : Math.min(sel + 1, all.length - 1)); e.preventDefault(); }
  else if (e.key === 'ArrowUp'){ pick(sel <= 0 ? 0 : sel - 1); e.preventDefault(); }
  else if (e.key === 'Escape'){
    if (sel > -1 && all[sel]) all[sel].classList.remove('sel');
    sel = -1; ft.innerHTML = DEF; e.preventDefault();
  }
});
